//! Rasterize the PDF generated by the export probe.
use anyhow::Result;
use std::{fs, path::PathBuf};

fn main() -> Result<()> {
    let directory = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../target/m0");
    let png = moino_preview::render_pdf_page(fs::read(directory.join("pagination.pdf"))?, 0)?;
    fs::write(directory.join("page-1.png"), png)?;
    Ok(())
}
